script = r'''
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
import os
src='/root/data/workbook.xlsx'
out='/root/output/result.xlsx'
wb=load_workbook(src, data_only=False)
ws=wb['Task']
# Identify data layout from inspection: Data rows 21:38, series codes in D21:D38, year values in H4:L4, data values in H21:L38.
# Step 1 lookup formulas
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            col=get_column_letter(c)
            ws.cell(r,c).value = f'=INDEX(Data!$H$21:$L$38, MATCH($D{r}, Data!$D$21:$D$38, 0), MATCH({col}$10, Data!$H$4:$L$4, 0))'
# Confirm block identities from indicator labels in column E.
blocks = {
    'committed_funding': (12,17, {ws.cell(r,5).value for r in range(12,18)}),
    'operating_spend': (19,24, {ws.cell(r,5).value for r in range(19,25)}),
    'approved_budget_base': (26,31, {ws.cell(r,5).value for r in range(26,32)}),
}
print('Block identity labels:')
for name,(start,end,labels) in blocks.items():
    print(f'  {name}: rows {start}-{end}, labels={sorted(labels)}')
# Step 2 net budget buffer formulas rows 35-40, same relative offset
for offset,r in enumerate(range(35,41)):
    cf_row = 12 + offset
    os_row = 19 + offset
    base_row = 26 + offset
    for c in range(8,13):
        col=get_column_letter(c)
        ws.cell(r,c).value = f'=({col}{cf_row}-{col}{os_row})/{col}{base_row}*100'
# Summary statistics label mapping rows 42-47, labels in E
for r in range(42,48):
    label = (ws.cell(r,5).value or '').strip().lower()
    for c in range(8,13):
        col=get_column_letter(c)
        if label == 'minimum':
            formula=f'=MIN({col}35:{col}40)'
        elif label == 'maximum':
            formula=f'=MAX({col}35:{col}40)'
        elif label == 'median':
            formula=f'=MEDIAN({col}35:{col}40)'
        elif label in ('simple mean','average','mean'):
            formula=f'=AVERAGE({col}35:{col}40)'
        elif label == '25th percentile':
            formula=f'=PERCENTILE({col}35:{col}40, 0.25)'
        elif label == '75th percentile':
            formula=f'=PERCENTILE({col}35:{col}40, 0.75)'
        else:
            raise ValueError(f'Unrecognized summary label row {r}: {ws.cell(r,5).value!r}')
        ws.cell(r,c).value = formula
# Weighted mean row 50
for c in range(8,13):
    col=get_column_letter(c)
    ws.cell(50,c).value = f'=SUMPRODUCT({col}35:{col}40, {col}26:{col}31) / SUM({col}26:{col}31)'
wb.save(out)
print(f'Saved {out}')
print('Formula samples written before save:')
for addr in ['H12','H19','H26','H35','H42','H43','H44','H45','H46','H47','H50']:
    print(f'  {addr}: {ws[addr].value}')
print('File size after save:', os.path.getsize(out))
'''
res=terminal("python3 - <<'PY'\n"+script+"\nPY", timeout=120, workdir='/root')
print(res['output'])
if res.get('exit_code') != 0:
    print('EXIT_CODE', res.get('exit_code'))"}
